def parse_duration(text):
    import re
    m = re.fullmatch(r"(?:(\d+)h)?(?:(\d+)m)?", text)
    if m is None or not (m.group(1) or m.group(2)):
        raise RuntimeError("not a duration")
    return int(m.group(1) or 0) * 60 + int(m.group(2) or 0)
